Section FPX_1. Context {fx : PropExec.FPState}.

(* [comment removed for export] *)
Definition atexit_state (mem : word -> option byte) (hs : list (Z * Z)) : Prop :=
  rdn RSEGS mem (Z_to_bv 64 0xfd05c) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0))            (* [comment removed for export] *)
  /\ match hs with
     | [] => rdn RSEGS mem (Z_to_bv 64 0xfd068) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0))  (* [comment removed for export] *)
     | _ => (Z.of_nat (length hs) <= 32)%Z
            /\ rdn RSEGS mem (Z_to_bv 64 0xfd068) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xfd070))           (* [comment removed for export] *)
            /\ rdn RSEGS mem (Z_to_bv 64 0xfd060) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 (Z.of_nat (length hs))))   (* [comment removed for export] *)
            /\ rdn RSEGS mem (Z_to_bv 64 0xfd070) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0))                 (* [comment removed for export] *)
            /\ (forall i f a, nth_error hs i = Some (f, a) ->
                   rdn RSEGS mem (Z_to_bv 64 (0xfd078 + 8 * Z.of_nat i)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 f))
                /\ rdn RSEGS mem (Z_to_bv 64 (0xfd178 + 8 * Z.of_nat i)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 a)))
     end.

