(* [comment removed for export] *)
Record foe_mem (m : word -> option byte) (sp s0v s1v s2v s3v : word) (hs : list (Z * Z)) : Prop := {
  fm_ra : rdn RSEGS m (Z_to_bv 64 (bv_unsigned sp - 24)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xad978));
  fm_s0 : rdn RSEGS m (Z_to_bv 64 (bv_unsigned sp - 32)) 8%nat = Some (word_to_le_bytes 8 s0v);
  fm_s1 : rdn RSEGS m (Z_to_bv 64 (bv_unsigned sp - 40)) 8%nat = Some (word_to_le_bytes 8 s1v);
  fm_s2 : rdn RSEGS m (Z_to_bv 64 (bv_unsigned sp - 48)) 8%nat = Some (word_to_le_bytes 8 s2v);
  fm_s3 : rdn RSEGS m (Z_to_bv 64 (bv_unsigned sp - 56)) 8%nat = Some (word_to_le_bytes 8 s3v);
  fm_nl : rdn RSEGS m (Z_to_bv 64 0xfd2a3) 1%nat = Some [Z_to_bv 8 0];
  fm_lock : rdn RSEGS m (Z_to_bv 64 0xfd05c) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0));
  fm_head : rdn RSEGS m (Z_to_bv 64 0xfd068) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0xfd070));
  fm_next : rdn RSEGS m (Z_to_bv 64 0xfd070) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0));
  fm_tab : forall i f a, nth_error hs i = Some (f, a) ->
             rdn RSEGS m (Z_to_bv 64 (0xfd078 + 8 * Z.of_nat i)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 f))
          /\ rdn RSEGS m (Z_to_bv 64 (0xfd178 + 8 * Z.of_nat i)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 a));
  fm_sok : store_ok RSEGS m (Z_to_bv 64 (bv_unsigned sp - 144)) 144%nat = true
}.

End FPX_1.

