Lemma atexit_state_nonempty : forall mem hs, hs <> [] -> atexit_state mem hs ->
  rdn RSEGS mem (Z_to_bv 64 0xfd05c) 4%nat = Some (word_to_le_bytes 4 (Z_to_bv 64 0))
